import { count, desc, eq } from 'drizzle-orm'
import type { LibSQLDatabase } from 'drizzle-orm/libsql'
import type { Post } from '#blog/domain/post'
import type { PostRepository } from '../../application/ports/post-repository'
import { posts } from '../db/schema'

/** PostRepository over the app database (Drizzle + libSQL). */
export const drizzlePostRepository = (db: LibSQLDatabase): PostRepository => ({
  async list({ limit, offset }) {
    const [items, [total]] = await Promise.all([
      db.select().from(posts).orderBy(desc(posts.createdAt)).limit(limit).offset(offset),
      db.select({ value: count() }).from(posts)
    ])
    return { items, total: total?.value ?? 0 }
  },
  async get(id) {
    return db.select().from(posts).where(eq(posts.id, id)).get()
  },
  async findBySlug(slug) {
    return db.select().from(posts).where(eq(posts.slug, slug)).get()
  },
  async create(post: Post) {
    await db.insert(posts).values(post)
    return post
  },
  async update(id, post: Post) {
    await db.update(posts).set(post).where(eq(posts.id, id))
    return post
  },
  async delete(id) {
    await db.delete(posts).where(eq(posts.id, id))
  }
})
